import ctypes,errno,json,os,stat,sys
libc=ctypes.CDLL(None,use_errno=True)
libc.fstatfs.argtypes=(ctypes.c_int,ctypes.c_void_p)
libc.fstatfs.restype=ctypes.c_int
CGROUP2_SUPER_MAGIC=0x63677270

def filesystem(fd):
 b=ctypes.create_string_buffer(256)
 if libc.fstatfs(fd,b):raise OSError(ctypes.get_errno(),'fstatfs')
 return ctypes.c_long.from_buffer(b).value

def inspect(path):
 owned=[];out={'path':path,'observations':{}}
 try:
  directory=os.open(path,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW|os.O_CLOEXEC);owned.append(directory)
  if filesystem(directory)!=CGROUP2_SUPER_MAGIC:raise OSError(errno.EINVAL,'not a native cgroup2 directory')
  for name in ('cgroup.procs','cgroup.controllers','cgroup.events','cgroup.type'):
   try:fd=os.open(name,os.O_RDONLY|os.O_NOFOLLOW|os.O_CLOEXEC,dir_fd=directory)
   except OSError as e:
    out['observations'][name]={'errno':e.errno}
    if name in ('cgroup.procs','cgroup.controllers') or e.errno!=errno.ENOENT:raise
    continue
   owned.append(fd)
   if filesystem(fd)!=CGROUP2_SUPER_MAGIC or not stat.S_ISREG(os.fstat(fd).st_mode):raise OSError(errno.EINVAL,'not an underlying cgroup2 core file')
   out['observations'][name]={'read':os.read(fd,65536).decode()}
  absent=[out['observations'][n].get('errno')==errno.ENOENT for n in ('cgroup.events','cgroup.type')]
  if all(absent):out['classification']='ROOT_CANDIDATE'
  elif not any(absent):out['classification']='NONROOT'
  else:raise OSError(errno.EINVAL,'inconsistent core-file observation')
 except OSError as e:out.update(classification='UNAVAILABLE',errno=e.errno,error=str(e))
 finally:
  for fd in reversed(owned):os.close(fd)
 return out

if __name__=='__main__':
 before=len(os.listdir('/proc/self/fd'))
 result=inspect(sys.argv[1]);result['fd_count_unchanged']=len(os.listdir('/proc/self/fd'))==before
 print(json.dumps(result))

